162: - name: Remove containers
163:   become: true
164:   community.docker.docker_container:
165:     name: "{{ item }}"
166:     state: absent
167:     force_kill: true
168:     keep_volumes: "{{ not (ovos_containers_docker_compose_remove_volumes | bool) }}"
169:   loop: "{{ ovos_containers_uninstall_target_ids | default([]) }}"
170:   when: ovos_containers_uninstall_target_ids | default([]) | length > 0
171: 
172: # Removal uses the image reference the container was created from, so only that
173: # reference is untagged, but an image is retained by ID as well as by reference,
174: # because a container which stays can hold the same image under a different
175: # reference. A leftover image is not worth failing the uninstall for either, it
176: # can still be referenced by another tag or by a container created in between.
177: - name: Remove container images
178:   become: true
179:   community.docker.docker_image_remove:
180:     name: "{{ item }}"
181:   loop: "{{ ovos_containers_uninstall_target_images | default([]) }}"

