 66:       --threshold {{ logclassify_threshold }}
 67:       --before-context {{ logclassify_before_context }}
 68:       --after-context {{ logclassify_after_context }}
 69:       {% if logclassify_local_dir != zuul.executor.log_root %}
 70:         {# Running on test instance directly #}
 71:         {% if logclassify_ara_database %}
 72:             {{ logclassify_tmp_dir }}/ara-report/ansible.sqlite
 73:         {% elif logclassify_local_dir %}
 74:             {{ logclassify_local_dir }}
 75:             --test-prefix {{ logclassify_logserver_dir }}
 76:         {% else %}
 77:             {{ logclassify_tmp_dir }}/job-output.txt
 78:         {% endif %}
 79:       {% else %}
 80:         {# Running on executor #}
 81:         {% if logclassify_ara_database %}
 82:             {{ logclassify_local_dir }}/ara-report/ansible.sqlite
 83:         {% elif logclassify_logserver_dir %}
 84:             {{ logclassify_local_dir }}
 85:         {% else %}
 86:             {{ logclassify_local_dir }}/job-output.txt
 87:         {% endif %}
 88:       {% endif %}
 89:       --html {{ logclassify_tmp_dir }}/log-classify.html
 90:       {% if logclassify_static_location %}--static-location {{ logclassify_static_location }}{% endif %}
 91:       {% for _path in logclassify_exclude_paths %}--exclude-path {{ _path }}{% endfor %}
 92:       {% for _path in logclassify_exclude_files %}--exclude-file {{ _path }}{% endfor %}
 93:   register: _model_run
 94:   failed_when: _model_run.rc not in [0, 4]
 95:   when:
 96:     - _model_check.rc == 0 or _model_build.rc == 0
 97: 
 98: - name: Fetch report
 99:   synchronize:
100:     src: "{{ logclassify_tmp_dir }}/log-classify.{{ item }}"
101:     dest: "{{ zuul.executor.log_root }}/log-classify.{{ item }}"
102:     mode: pull
103:   with_items:
104:     - html
105:     - json
106:   when:
107:     - _model_check.rc == 0 or _model_build.rc == 0
108:     - _model_run.rc == 0
109: 
110: - name: Fetch model
111:   synchronize:
112:     src: "{{ _model_path }}"
113:     dest: "{{ zuul.executor.log_root }}/model.clf"
114:     mode: pull
115:   when:
116:     - _model_check.rc == 4
117:     - _model_build.rc == 0
118: 
119: - name: Write model name
120:   copy:
121:     content: "{{ _model_name }}"
122:     dest: "{{ zuul.executor.log_root }}/model.name"
123:   delegate_to: localhost
124:   when:
125:     - _model_check.rc == 4
126:     - _model_build.rc == 0
127: 
128: - name: Return the report artifact
129:   when:
130:     - _model_check.rc == 0 or _model_build.rc == 0
131:     - _model_run.rc == 0

