127:       changed_when: "'changed:' in windows_debloat_win32.stdout"
128: 
129:     - name: Remove auto-launch Run entries from every user hive
130:       ansible.windows.win_shell: |
131:         $ErrorActionPreference = 'Stop'
132:         $patterns = @({{ windows_debloat_user_run_keys | default([]) | map('to_json') | join(', ') }})
133:         if (-not (Get-PSDrive HKU -ErrorAction SilentlyContinue)) {
134:           New-PSDrive -Name HKU -PSProvider Registry -Root HKEY_USERS | Out-Null
135:         }
136:         $runKeys = @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run')
137:         Get-ChildItem HKU:\ | Where-Object { $_.PSChildName -notmatch '_Classes$|^\.DEFAULT$' } |
138:           ForEach-Object { $runKeys += "HKU:\$($_.PSChildName)\Software\Microsoft\Windows\CurrentVersion\Run" }
139:         $removed = @()
140:         foreach ($key in $runKeys) {
141:           if (-not (Test-Path $key)) { continue }
142:           $props = (Get-Item $key).Property
143:           foreach ($name in $props) {
144:             foreach ($p in $patterns) {
145:               if ($name -like $p) {
146:                 Remove-ItemProperty -Path $key -Name $name
147:                 $removed += $name
148:                 break
149:               }
150:             }
151:           }
152:         }
153:         if ($removed) { "changed: $(($removed | Select-Object -Unique) -join ', ')" } else { 'ok' }
154:       register: windows_debloat_runkeys
155:       changed_when: "'changed:' in windows_debloat_runkeys.stdout"
156:       when: windows_debloat_user_run_keys | default([]) | length > 0

