159:       {{ (common_kernel_params_base_add | default([]))
160:          + (common_kernel_params_add | default([])) }}
161:     common_kernel_params_remove_merged: >-
162:       {{ (common_kernel_params_base_remove | default([]))
163:          + (common_kernel_params_remove | default([])) }}
164: 
165: - name: Build combined kernel param list
