171: - name: Validate kernel params do not touch protected keys
172:   vars:
173:     common_kernel_params_protected_regex: '^(root=|init=|systemd\.unit=|resume=|cryptdevice=|rd\.|BOOT_IMAGE=)'
174:   ansible.builtin.assert:
175:     that:
176:       - item is not match(common_kernel_params_protected_regex)
