182: 
183: - name: Read current kernel parameters via grubby
184:   ansible.builtin.command:
185:     cmd: grubby --info=ALL
186:   register: common_kernel_params_info
187:   changed_when: false
188:   failed_when: false
189:   when: common_kernel_params_all | length > 0
190: 
191: - name: Parse current kernel parameters
192:   ansible.builtin.set_fact:
193:     common_kernel_params_current_lists: >-
194:       {%- set result = [] -%}
195:       {%- for line in common_kernel_params_info.stdout_lines | default([]) -%}
196:         {%- if line is match('^args=') -%}
197:           {%- set raw = line | regex_replace('^args=', '') -%}
198:           {%- set raw = raw | regex_replace('^"(.*)"$', '\\1') -%}
199:           {%- set raw = raw | regex_replace("^'(.*)'$", '\\1') -%}
200:           {%- set tokens = (raw | trim).split() if (raw | trim | length) > 0 else [] -%}
201:           {%- set _ = result.append(tokens) -%}
202:         {%- endif -%}
203:       {%- endfor -%}
204:       {{ result }}
205:   when: common_kernel_params_all | length > 0
206: 
207: - name: Build current kernel parameter sets
208:   ansible.builtin.set_fact:
209:     common_kernel_params_current_union: >-
210:       {%- set union = [] -%}
211:       {%- for lst in common_kernel_params_current_lists -%}
212:         {%- for token in lst -%}
213:           {%- if token not in union -%}
214:             {%- set _ = union.append(token) -%}
215:           {%- endif -%}
216:         {%- endfor -%}
217:       {%- endfor -%}
218:       {{ union }}
219:     common_kernel_params_current_intersection: >-
220:       {%- set lists = common_kernel_params_current_lists -%}
221:       {%- if lists | length == 0 -%}
222:         []
223:       {%- else -%}
224:         {%- set intersection = lists[0] | list -%}
225:         {%- for lst in lists[1:] -%}
226:           {%- set filtered = [] -%}
227:           {%- for token in intersection -%}
228:             {%- if token in lst -%}
229:               {%- set _ = filtered.append(token) -%}
230:             {%- endif -%}
231:           {%- endfor -%}
232:           {%- set intersection = filtered -%}
233:         {%- endfor -%}
234:         {{ intersection }}
235:       {%- endif -%}
236:   when: common_kernel_params_all | length > 0
237: 
238: - name: Normalize kernel param adds
239:   ansible.builtin.set_fact:
240:     common_kernel_params_add_deduped: >-
241:       {%- set ns = namespace(result=[]) -%}
242:       {%- for token in common_kernel_params_add_merged -%}

